"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[71615],{92135(e,n,o){o.r(n),o.d(n,{assets:()=>a,contentTitle:()=>i,default:()=>m,frontMatter:()=>l,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"general/tenable-nessus-agent-install-script-for-tenable-io","title":"Tenable Nessus Agent Install Script For Tenable Io","description":"By jeff-codecov","source":"@site/docs/general/tenable-nessus-agent-install-script-for-tenable-io.md","sourceDirName":"general","slug":"/general/tenable-nessus-agent-install-script-for-tenable-io","permalink":"/jc-community-archive/general/tenable-nessus-agent-install-script-for-tenable-io","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Tenable Nessus Agent Install Script For Tenable Io","description":"By jeff-codecov"},"sidebar":"docs","previous":{"title":"Temporary Elevated Privileges Is Here","permalink":"/jc-community-archive/general/temporary-elevated-privileges-is-here"},"next":{"title":"Thank You For Making Work Happen","permalink":"/jc-community-archive/general/thank-you-for-making-work-happen"}}');var s=o(74848),r=o(28453);const l={title:"Tenable Nessus Agent Install Script For Tenable Io",description:"By jeff-codecov"},i=void 0,a={},d=[];function c(e){const n={code:"code",p:"p",pre:"pre",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.p,{children:"This script assumes you are using Tenable IO to manage your nessus agents deployed to endpoints,\xa0 and you are curl'ing your nessus .dmg file from a Google drive folder that is publicly accessible. Modify as needed, then configure as a Command that runs as root."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'#!/bin/bash\n\n# Install script for Tenable agent for Mac. Assumes the .dmg file is publicly shared in a Gdrive folder. Set vars for the unique FILEID below.\n# Tested with NessusAgent-10.1.3.dmg and MacOS 12.3/12.4\n# *NOTE* this template is only designed to work with DMG files and does not support .pkg, .zip files or DMGs that contain .pkg installers.\n# Run as root in JumpCloud\n\n#################################################\n# VARS - Edit as necessary\n###\nexport FILEID=xxxxxxx\nexport FILENAME=tenable.dmg\n\nexport TENABLE_LINKING_KEY=xxxxxx\nexport DOMAIN=acme.com\nexport DEVICE_GROUP=mac_hosts\n###\n#################################################\n\n# Create Temp Folder\n#\nDATE=$(date \'+%Y-%m-%d-%H-%M-%S\')\nTempFolder="Download-$DATE"\nmkdir /tmp/$TempFolder\n\n# Navigate to Temp Folder\n#\ncd /tmp/$TempFolder\n\n# Download tenable binary from Gdrive folder. Must use a publicly shared link, and you need the fieldid from it.\n# See this URL for how to get the fileid value:  https://bytesbin.com/how-to-download-a-large-file-from-google-drive-quickly\n#\ncurl -L -c cookies.txt \'https://docs.google.com/uc?export=download&id=\'$FILEID | sed -rn \'s/.*confirm=([0-9A-Za-z_]+).*/\\1/p\' > confirm.txt\ncurl -L -b cookies.txt -o $FILENAME \'https://docs.google.com/uc?export=download&id=\'$FILEID\'&confirm=\'$(<confirm.txt)\nrm -f confirm.txt cookies.txt\n\n# Capture name of Download File\n#\nDownloadFile="$(ls)"\necho "Downloaded $DownloadFile to /tmp/$TempFolder"\n\n# Verifies DMG File\n#\nregex=\'\\.dmg$\'\nif [[ $DownloadFile =~ $regex ]]; then\n    DMGFile="$(echo "$DownloadFile")"\n    echo "DMG File Found: $DMGFile"\nelse\n    echo "File: $DownloadFile is not a DMG"\n    rm -r /tmp/$TempFolder\n    echo "Deleted /tmp/$TempFolder"\n    exit 1\nfi\n\n# Mount DMG File -nobrowse prevents the volume from popping up in Finder\n#\nhdiutilAttach=$(hdiutil attach /tmp/$TempFolder/$DMGFile -nobrowse)\necho "Used hdiutil to mount $DMGFile "\n\nerr=$?\nif [ ${err} -ne 0 ]; then\n    echo "Could not mount $DMGFile Error: ${err}"\n    rm -r /tmp/$TempFolder\n    echo "Deleted /tmp/$TempFolder"\n    exit 1\nfi\n\nregex=\'\\/Volumes\\/.*\'\nif [[ $hdiutilAttach =~ $regex ]]; then\n    DMGVolume="${BASH_REMATCH[@]}"\n    echo "Located DMG Volume: $DMGVolume"\nelse\n    echo "DMG Volume not found"\n    rm -r /tmp/$TempFolder\n    echo "Deleted /tmp/$TempFolder"\n    exit 1\nfi\n\n# Identify the mount point for the DMG file\n#\nDMGMountPoint="$(hdiutil info | grep "$DMGVolume" | awk \'{ print $1 }\')"\necho "Located DMG Mount Point: $DMGMountPoint"\n\n# cd to directory where .pkg file is mounted to from the .dmg (which has spaces, so need to escape and hardcode)\n#\ncd /Volumes/Nessus\\ Agent\\ Install\n\n# Now install the agent\n#\ninstaller -pkg /Volumes/Nessus\\ Agent\\ Install/Install\\ Nessus\\ Agent.pkg -target /Applications\n\n# Create user name var for enrolling nessus agent in Tenable IO\n#\nHOSTID=$(hostname | sed \'s/ /_/g\' | sed \'s/\\.local//g\')\necho "Host ID is: $HOSTID"\n\n# Enroll agent to Tenable.IO\n# Assumes you have a device group (e.g. mac_hosts), a host value (e.g. acme.com), and a tenable linking key.\n#\n/Library/NessusAgent/run/sbin/nessuscli agent link --key=$TENABLE_LINKING_KEY --host=$DOMAIN --groups=$DEVICE_GROUP --name=$HOSTID --cloud\n\n# Unmount the DMG file\n#\nhdiutil detach $DMGMountPoint\n\n# Remove Temp Folder and download\n#\nrm -r /tmp/$TempFolder\necho "Deleted /tmp/$TempFolder"\n'})})]})}function m(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,n,o){o.d(n,{R:()=>l,x:()=>i});var t=o(96540);const s={},r=t.createContext(s);function l(e){const n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:l(e.components),t.createElement(r.Provider,{value:n},e.children)}}}]);